        ["hubNotSigned"] = ["لم يُعثر على توقيع مضمّن مقبول", "No accepted embedded signature found", "Aucune signature intégrée acceptée", "No se encontró firma integrada aceptada"],
        ["hubUntrusted"] = ["تعذر التحقق من الثقة بالتوقيع", "Signature trust could not be verified", "Confiance dans la signature non vérifiée", "No se pudo verificar la confianza de la firma"],
