        ["hubEncryption"] = ["حالة حماية BitLocker المبلّغ عنها", "Reported BitLocker protection state", "Protection BitLocker déclarée", "Estado de protección BitLocker reportado"],
        ["hubLastUpdateSearch"] = ["آخر بحث ناجح مخزّن عن التحديثات", "Cached last successful update search", "Dernière recherche de mises à jour réussie en cache", "Última búsqueda de actualizaciones correcta en caché"],
        ["hubLastUpdateInstall"] = ["آخر تثبيت تحديث ناجح مخزّن", "Cached last successful update installation", "Dernière installation réussie en cache", "Última instalación de actualización correcta en caché"],
        ["hubUpdates"] = ["معلومات تحديث ويندوز", "Windows Update information", "Informations Windows Update", "Información de Windows Update"],
        ["hubSecurityLimits"] = ["تُعرض حالة المصادر المقروءة فقط؛ قد تتطلب بعض البيانات صلاحيات غير متاحة. تواريخ التحديث مخزنة ولا تثبت أن كل التحديثات مثبتة. حالة حماية BitLocker لا تقيس اكتمال التشفير. لا تُعدّل إعدادات الأمان هنا.", "Only readable source states are shown; some data may require unavailable privileges. Cached update dates do not prove all updates are installed. BitLocker protection status is not encryption completion. No security setting is changed.", "Seuls les états lisibles sont affichés ; certains privilèges peuvent manquer. Les dates en cache ne prouvent pas que tout est à jour. La protection BitLocker ne mesure pas la fin du chiffrement. Aucun réglage modifié.", "Solo se muestran estados legibles; pueden faltar privilegios. Las fechas en caché no prueban que todas las actualizaciones estén instaladas. La protección BitLocker no mide el cifrado completo. No se cambian ajustes de seguridad."],
        ["hubReputationLookup"] = ["سمعة التجزئة الاختيارية", "Optional hash reputation", "Réputation facultative de l’empreinte", "Reputación opcional del hash"],
        ["hubReputationPrivacy"] = ["اختياري: يُرسل SHA-256 فقط إلى VirusTotal بمفتاحك، دون الملف أو مساره. قد يكشف الاستعلام هوية الملف للخدمة، وتطبق حدودها وشروطها.", "Optional: send only SHA-256 to VirusTotal using your key, never the file or path. The query can identify the file to the service; its limits and terms apply.", "Facultatif : seul le SHA-256 est envoyé à VirusTotal avec votre clé, jamais le fichier ni son chemin. L’empreinte peut identifier le fichier ; limites et conditions du service applicables.", "Opcional: envía solo SHA-256 a VirusTotal con tu clave, nunca el archivo ni su ruta. La consulta puede identificar el archivo; se aplican los límites y condiciones del servicio."],
        ["hubReputationKey"] = ["مفتاح API لخدمة VirusTotal", "VirusTotal API key", "Clé API VirusTotal", "Clave API de VirusTotal"],
        ["hubSaveReputationKey"] = ["حفظ مفتاح VirusTotal", "Save VirusTotal key", "Enregistrer la clé VirusTotal", "Guardar clave de VirusTotal"],
        ["hubReputationConsent"] = ["أوافق على إرسال SHA-256 لهذا الملف في الاستعلام القادم فقط", "Allow this file’s SHA-256 in the next query only", "Autoriser le SHA-256 de ce fichier pour la prochaine requête uniquement", "Autorizar el SHA-256 de este archivo solo en la próxima consulta"],
        ["hubCheckReputation"] = ["الاستعلام عن سمعة التجزئة", "Query hash reputation", "Consulter la réputation", "Consultar reputación del hash"],
        ["hubReputationNeedsConsent"] = ["راجع الملف ثم وافق على إرسال تجزئته لهذا الطلب.", "Review the file, then approve sending its hash for this request.", "Vérifiez le fichier, puis autorisez son empreinte pour cette requête.", "Revisa el archivo y autoriza enviar su hash para esta solicitud."],
        ["hubReputationNeedsKey"] = ["أضف مفتاح VirusTotal واحفظه أولًا.", "Add and save a VirusTotal key first.", "Ajoutez et enregistrez une clé VirusTotal d’abord.", "Añade y guarda primero una clave de VirusTotal."],
        ["hubReputation"] = ["المحركات التي أبلغت عن اشتباه أو ضرر / إجمالي المحركات", "Engines reporting suspicious or malicious / total engines", "Moteurs signalant suspect ou malveillant / total", "Motores que reportan sospechoso o malicioso / total"],
        ["hubHashUnknown"] = ["لا توجد نتيجة لهذه التجزئة لدى الخدمة", "No service result for this hash", "Aucun résultat du service pour cette empreinte", "Sin resultado del servicio para este hash"],
        ["hubReputationDate"] = ["وقت آخر تحليل لدى الخدمة", "Service’s last analysis time", "Dernière analyse du service", "Hora del último análisis del servicio"],
        ["hubReputationLimits"] = ["هذه نتيجة سابقة لدى خدمة خارجية، وقد تكون قديمة أو تخطئ. عدد صفر أو تجزئة غير معروفة لا يثبتان الأمان، والتوقيع ليس بديلًا لتحليل الحماية.", "This is a prior third-party result and may be stale or wrong. Zero flags or an unknown hash do not prove safety; a signature is not a substitute for protection analysis.", "Résultat antérieur d’un tiers, potentiellement ancien ou erroné. Zéro alerte ou empreinte inconnue ne prouve pas la sécurité ; une signature ne remplace pas l’analyse antivirus.", "Es un resultado previo de terceros y puede estar desactualizado o equivocado. Cero alertas o un hash desconocido no prueban seguridad; una firma no sustituye el análisis antivirus."],
        ["hubNetworkScope"] = ["بعد الموافقة فقط: حل DNS وست محاولات ICMP إلى الهدف الذي تختاره. يمكنك تكرار القياس خمس مرات كحد أقصى. لا يجري الاختبار عند فتح الصفحة.", "After consent only: DNS resolution and six ICMP probes to your target. Optionally repeat up to five measurements. Opening the page runs no test.", "Après autorisation seulement : DNS et six sondes ICMP vers votre cible. Jusqu’à cinq mesures facultatives. Aucun test à l’ouverture.", "Solo con autorización: resolución DNS y seis sondas ICMP al destino elegido. Hasta cinco mediciones opcionales. Abrir la página no ejecuta pruebas."],
        ["hubHost"] = ["اسم المضيف أو عنوان IP", "Hostname or IP address", "Nom d’hôte ou adresse IP", "Nombre de host o dirección IP"],
        ["hubNetworkConsent"] = ["أوافق على طلب DNS ومحاولات ICMP إلى الهدف المحدد", "Allow DNS and ICMP probes to the selected target", "Autoriser DNS et les sondes ICMP vers la cible choisie", "Autorizar DNS y sondas ICMP al destino seleccionado"],
        ["hubNetworkRepeat"] = ["تكرار القياس حتى خمس مرات، بفاصل ١٠ ثوانٍ بعد كل قياس", "Repeat up to five times, waiting ten seconds after each measurement", "Répéter jusqu’à cinq fois, avec dix secondes après chaque mesure", "Repetir hasta cinco veces, esperando diez segundos tras cada medición"],
        ["hubMeasureNetwork"] = ["بدء قياس الشبكة", "Measure network", "Mesurer le réseau", "Medir la red"],
        ["hubNetworkNeedsConsent"] = ["راجع الهدف ووافق على محاولات الاتصال أولًا.", "Review the target and authorize the probes first.", "Vérifiez la cible et autorisez les sondes d’abord.", "Revisa el destino y autoriza primero las sondas."],
        ["hubDnsDuration"] = ["زمن استجابة محلل DNS", "DNS resolver time", "Temps de résolution DNS", "Tiempo de resolución DNS"],
        ["hubPingReplies"] = ["ردود ICMP / المحاولات", "ICMP replies / attempts", "Réponses ICMP / tentatives", "Respuestas ICMP / intentos"],
