        ["hubLatencySpread"] = ["فرق أكبر وأصغر زمن ذهاب وعودة", "Maximum minus minimum round-trip time", "Écart entre aller-retour maximal et minimal", "Diferencia entre tiempos máximo y mínimo"],
        ["hubAdapters"] = ["حالة محولات الشبكة المقروءة", "Readable network adapter states", "États lisibles des cartes réseau", "Estados legibles de adaptadores de red"],
        ["hubWifiQuality"] = ["جودة إشارة Wi-Fi المبلّغ عنها", "Reported Wi-Fi signal quality", "Qualité du signal Wi-Fi déclarée", "Calidad de señal Wi-Fi reportada"],
        ["hubWifiLink"] = ["معدل ارتباط Wi-Fi المبلّغ عنه", "Reported Wi-Fi link rate", "Débit de liaison Wi-Fi déclaré", "Velocidad de enlace Wi-Fi reportada"],
        ["hubLatencyChange"] = ["تغيّر المتوسط عن القياس السابق للهدف نفسه", "Mean change from the previous measurement of this target", "Variation moyenne depuis la mesure précédente de cette cible", "Cambio medio respecto a la medición anterior del mismo destino"],
        ["hubDnsFailed"] = ["تعذر حل اسم الهدف في هذه العينة؛ لا يثبت ذلك تعطل الإنترنت كله.", "Target name resolution failed in this sample; this does not prove the whole connection is down.", "La résolution de la cible a échoué ; cela ne prouve pas une panne de toute la connexion.", "Falló la resolución del destino en esta muestra; no demuestra una caída de toda la conexión."],
        ["hubIcmpUnknown"] = ["لم تصل ردود ICMP كافية. قد يمنعها الهدف أو الجدار الناري؛ لا يمكن اعتبار ذلك وحده انقطاعًا.", "Insufficient ICMP replies. The target or firewall may block them; this alone cannot establish an outage.", "Réponses ICMP insuffisantes. La cible ou le pare-feu peut les bloquer ; cela seul n’établit pas une panne.", "Respuestas ICMP insuficientes. El destino o firewall puede bloquearlas; esto por sí solo no establece una interrupción."],
        ["hubPacketLoss"] = ["لم ترد بعض محاولات ICMP في هذه العينة. راجع التكرار واحتمال التصفية.", "Some ICMP attempts received no reply in this sample. Review repeat measurements and possible filtering.", "Certaines sondes ICMP n’ont pas reçu de réponse. Examinez répétitions et filtrage possible.", "Algunos intentos ICMP no recibieron respuesta. Revisa mediciones repetidas y posibles filtros."],
        ["hubLatencyHigh"] = ["متوسط زمن الرد مرتفع في هذه العينة؛ يعتمد التفسير على بُعد الهدف والمسار.", "Mean reply time is high in this sample; interpretation depends on target distance and route.", "Le temps moyen est élevé dans cet échantillon ; distance et route doivent être prises en compte.", "El tiempo medio es alto en esta muestra; su interpretación depende de la distancia y ruta."],
        ["hubNetworkLimits"] = ["قياس قصير لـ DNS وICMP، وليس اختبار سرعة أو تدقيقًا كاملًا للإنترنت. الحجب، والمسار، وبُعد الهدف قد تؤثر في النتائج. لا تُعدّل الشبكة تلقائيًا.", "A short DNS/ICMP measurement, not a speed test or complete internet audit. Filtering, route and target distance can affect results. No network changes are made automatically.", "Mesure DNS/ICMP courte, pas test de débit ni audit complet. Filtrage, route et distance influencent les résultats. Aucun changement réseau automatique.", "Medición breve de DNS/ICMP, no prueba de velocidad ni auditoría completa. Los filtros, ruta y distancia pueden afectar resultados. No hay cambios automáticos de red."],
        ["hubWifiLimits"] = ["معدل الارتباط ليس سرعة الإنترنت. قد تغيب قراءة Wi-Fi بسبب الصلاحيات أو نوع الاتصال. لا يُحفظ SSID أو BSSID ضمن هذه القراءات.", "Link rate is not internet throughput. Wi-Fi readings may be unavailable because of permissions or connection type. SSID/BSSID are not retained in these readings.", "Le débit de liaison n’est pas celui d’Internet. Permissions ou type de connexion peuvent empêcher les mesures Wi-Fi. Aucun SSID/BSSID conservé.", "La velocidad del enlace no es la de Internet. Los permisos o tipo de conexión pueden impedir lecturas Wi-Fi. No se conservan SSID/BSSID."],
        ["hubNetworkHistoryPrivacy"] = ["الحفظ اختياري ومحلي بحماية حساب ويندوز. قد يتضمن الهدف وأسماء المحولات والأوقات والقياسات؛ لا يُرفع تلقائيًا.", "Saving is optional and locally protected by your Windows account. It may include targets, adapter names, times and readings; it is never uploaded automatically.", "Enregistrement facultatif, protégé localement par le compte Windows. Cibles, noms de cartes, heures et mesures peuvent être inclus, sans envoi automatique.", "Guardar es opcional y queda protegido localmente por tu cuenta de Windows. Puede incluir destinos, adaptadores, horas y lecturas, sin envío automático."],
        ["hubMeasuringNetwork"] = ["جارٍ قياس الشبكة…", "Measuring network…", "Mesure du réseau…", "Midiendo la red…"],
        ["hubNetworkIdle"] = ["لا يوجد قياس شبكة جارٍ.", "No network measurement is running.", "Aucune mesure réseau en cours.", "No hay una medición de red en curso."],
        ["hubMeasurementHistory"] = ["القياسات السابقة", "Measurement history", "Historique des mesures", "Historial de mediciones"],
        ["hubClearMarks"] = ["مسح علامات العَرَض المؤقتة", "Clear in-memory symptom markers", "Effacer les repères temporaires", "Borrar marcas temporales del síntoma"],
        ["hubSampleTable"] = ["قراءة جدول العينات", "Read sample values", "Lire les valeurs mesurées", "Leer valores de las muestras"],
        ["hubTime"] = ["الوقت", "Time", "Heure", "Hora"],
        ["hubChooseFolder"] = ["اختيار مجلد محلي", "Choose local folder", "Choisir un dossier local", "Elegir carpeta local"],
        ["hubSelectExternalFile"] = ["اختيار ملف من وحدة التخزين الخارجية", "Choose a file on external storage", "Choisir un fichier sur le stockage externe", "Elegir archivo del almacenamiento externo"],
        ["hubAllFiles"] = ["جميع الملفات", "All files", "Tous les fichiers", "Todos los archivos"],
        ["hubFolderScope"] = ["المجلد المحدد", "Selected folder", "Dossier sélectionné", "Carpeta seleccionada"],
        ["hubFilePath"] = ["مسار الملف", "File path", "Chemin du fichier", "Ruta del archivo"],
        ["hubStorageScope"] = ["تُقرأ بيانات المجلد الذي تختاره فقط، مع حدود للوقت وعدد العناصر وتجاوز الروابط. الإجمالي حجم الملفات المقروءة في العينة، وليس مساحة القرص كلها. لا يُحذف شيء أثناء الفحص.", "Only the chosen folder is inspected, with time/item limits and linked paths skipped. Totals cover readable sampled files, not the whole disk. Inspection deletes nothing.", "Seul le dossier choisi est examiné, avec limites de temps et d’éléments, sans liens. Les totaux couvrent les fichiers lisibles échantillonnés, pas tout le disque. Rien n’est supprimé.", "Solo se revisa la carpeta elegida, con límites de tiempo y elementos, omitiendo enlaces. El total cubre archivos legibles de la muestra, no todo el disco. No se elimina nada."],
        ["hubFindDuplicates"] = ["قراءة محتوى المرشحين للتحقق من التكرار باستخدام SHA-256", "Read candidate contents to verify duplicates with SHA-256", "Lire les candidats pour vérifier les doublons par SHA-256", "Leer candidatos para verificar duplicados mediante SHA-256"],
        ["hubInspectStorage"] = ["فحص المجلد المحدد", "Inspect selected folder", "Examiner le dossier choisi", "Revisar carpeta seleccionada"],
        ["hubStorageSummary"] = ["{0} ملف مقروء · حجم العينة {1}", "{0} files inspected · {1} sampled size", "{0} fichiers examinés · {1} échantillonnés", "{0} archivos revisados · {1} en la muestra"],
        ["hubFolderBreakdown"] = ["توزيع حجم العينة حسب المجلد", "Sample size by folder", "Taille échantillonnée par dossier", "Tamaño de la muestra por carpeta"],
        ["hubLargestFiles"] = ["أكبر الملفات — حتى ٢٠ ملفًا", "Largest files — up to 20 shown", "Plus gros fichiers — jusqu’à 20 affichés", "Archivos más grandes — hasta 20 mostrados"],
        ["hubDuplicateSets"] = ["مجموعات متطابقة بالتجزئة", "Hash-matched duplicate sets", "Groupes aux empreintes identiques", "Grupos con hashes idénticos"],
        ["hubDuplicatesNotScanned"] = ["لم تُقرأ محتويات الملفات للتحقق من التكرار في هذا الفحص.", "File contents were not read for duplicate verification in this inspection.", "Le contenu n’a pas été lu pour vérifier les doublons lors de cet examen.", "No se leyó el contenido para verificar duplicados en esta revisión."],
        ["hubNoDuplicatesInSample"] = ["لم تُثبت تطابقات ضمن الملفات التي جرت تجزئتها؛ قد تبقى ملفات غير مفحوصة.", "No duplicates established among hashed files; some files may remain unverified.", "Aucun doublon établi parmi les fichiers calculés ; certains restent peut-être non vérifiés.", "No se establecieron duplicados entre archivos con hash; otros pueden quedar sin verificar."],
        ["hubDuplicateSummary"] = ["{0} ملفات متطابقة بالتجزئة · {1} لكل ملف", "{0} matching files · {1} each", "{0} fichiers correspondants · {1} chacun", "{0} archivos coincidentes · {1} cada uno"],
        ["hubDuplicatesLimits"] = ["التطابق يعتمد على SHA-256 لمحتوى الملفات الكامل ضمن حدود التجزئة، مع مراجعة تغيّر الحجم والوقت. الملفات الكبيرة أو المتغيرة أو غير المقروءة تُستثنى. لا تُحذف الملفات المكررة تلقائيًا.", "Matches use SHA-256 of full file contents within hashing limits, checking size/time changes. Large, changed or unreadable files are excluded. Duplicates are never deleted automatically.", "Correspondances par SHA-256 du contenu complet dans les limites, avec contrôle taille/date. Fichiers gros, modifiés ou illisibles exclus. Aucun doublon supprimé automatiquement.", "Las coincidencias usan SHA-256 del contenido completo dentro de los límites, comprobando tamaño y fecha. Se excluyen archivos grandes, cambiados o ilegibles. No se eliminan duplicados automáticamente."],
        ["hubInspectedFiles"] = ["الملفات المقروءة في العينة", "Files inspected in sample", "Fichiers examinés dans l’échantillon", "Archivos revisados en la muestra"],
        ["hubInspectedBytes"] = ["مجموع بايتات الملفات المقروءة", "Total inspected file bytes", "Total des octets examinés", "Total de bytes de archivos revisados"],
        ["hubLinksSkipped"] = ["تُجاوزت مسارات مرتبطة؛ لم يُتبع محتواها.", "Linked paths were skipped; their contents were not followed.", "Chemins liés ignorés ; leur contenu n’a pas été suivi.", "Se omitieron rutas enlazadas; no se siguió su contenido."],
        ["hubHashLimit"] = ["بلغت التجزئة حد الحجم أو عدد الملفات؛ لا تشمل النتيجة كل المرشحين.", "A hashing size/count limit was reached; not all candidates are covered.", "Limite de taille/nombre pour les empreintes atteinte ; candidats incomplets.", "Se alcanzó un límite de tamaño o cantidad de hashes; no cubre todos los candidatos."],
        ["hubCleanup"] = ["تنظيف ملفات مؤقتة بمراجعة مسبقة", "Reviewed temporary-file cleanup", "Nettoyage temporaire après examen", "Limpieza temporal revisada"],
        ["hubCleanupLimits"] = ["المعاينة لمجلد Temp الخاص بالمستخدم فقط: أنواع مؤقتة محددة أقدم من ٧ أيام، حتى ٦٤ MiB للملف و٢٠٠ مرشح. تُستبعد الملفات المحمية والمرتبطة. اختر الملفات وراجع مساراتها؛ يُطلب نقلها إلى سلة المحذوفات، وقد يعرض ويندوز تحذيرًا إن تعذر ذلك. يمكنك الإلغاء.", "Preview covers only the user Temp folder: selected temporary types older than seven days, up to 64 MiB each and 200 candidates. Protected/linked files are excluded. Select and review paths; recycling is requested, and Windows may warn if unavailable. You can cancel.", "Aperçu limité au Temp utilisateur : types temporaires définis de plus de sept jours, 64 Mio par fichier et 200 candidats. Fichiers protégés/liés exclus. Choisissez et vérifiez les chemins ; corbeille demandée, avec avertissement Windows si impossible. Annulation possible.", "La vista previa cubre solo Temp del usuario: tipos temporales definidos de más de siete días, hasta 64 MiB por archivo y 200 candidatos. Se excluyen protegidos y enlaces. Selecciona y revisa las rutas; se solicita papelera y Windows puede advertir si no es posible. Puedes cancelar."],
        ["hubPreviewCleanup"] = ["معاينة الملفات المؤقتة المسموح بها", "Preview eligible temporary files", "Prévisualiser les fichiers temporaires admissibles", "Ver archivos temporales permitidos"],
        ["hubCleanupAcknowledge"] = ["راجعت الملفات المحددة وأفهم أن إزالة الملفات إجراء يغيّر الجهاز", "I reviewed the selected files and understand removal changes the device", "J’ai vérifié les fichiers choisis et compris que leur suppression modifie l’appareil", "Revisé los archivos seleccionados y entiendo que quitarlos modifica el equipo"],
        ["hubRecycleSelected"] = ["مراجعة إزالة الملفات المحددة", "Review selected-file removal", "Vérifier la suppression choisie", "Revisar eliminación seleccionada"],
        ["hubCleanupChoose"] = ["اختر ملفات من المعاينة وفعّل إقرار المراجعة أولًا.", "Select previewed files and acknowledge review first.", "Choisissez des fichiers de l’aperçu et confirmez leur examen.", "Selecciona archivos de la vista previa y confirma primero su revisión."],
        ["hubCleanupBatchLimit"] = ["يمكن مراجعة حتى ١٠ ملفات في عملية تنظيف واحدة.", "Review at most ten files in one cleanup batch.", "Examinez au maximum dix fichiers par nettoyage.", "Revisa como máximo diez archivos por operación de limpieza."],
        ["hubCleanupConfirm"] = ["هل توافق على إزالة الملفات ذات المسارات التالية فقط؟ سيُطلب نقلها إلى سلة المحذوفات. إذا حذّر ويندوز من حذف نهائي بدلًا منها، راجع تحذيره ويمكنك الإلغاء. تُراجع صلاحية الملفات مجددًا قبل الإجراء.", "Allow removal of only the exact file paths below? Recycling will be requested. If Windows warns of permanent deletion instead, review its warning and cancel if needed. Files are checked again before the operation.", "Autoriser la suppression des seuls chemins ci-dessous ? La corbeille sera demandée. Si Windows avertit d’une suppression définitive, examinez l’avertissement et annulez au besoin. Les fichiers sont revérifiés avant l’opération.", "¿Autorizar quitar solo las rutas exactas siguientes? Se solicitará la papelera. Si Windows advierte eliminación permanente, revisa el aviso y cancela si procede. Los archivos se comprueban de nuevo antes de actuar."],
        ["hubCleanupResult"] = ["أبلغت عملية ويندوز عن إزالة {0} من {1} ملف محدد.", "Windows reported {0} of {1} selected files removed.", "Windows a signalé {0} fichiers retirés sur {1} sélectionnés.", "Windows reportó {0} de {1} archivos seleccionados retirados."],
        ["hubCleanupAborted"] = ["أُلغيت العملية أو حدث خطأ؛ تحقق من حالة الملفات.", "The operation was canceled or encountered an error; check file state.", "Opération annulée ou en erreur ; vérifiez l’état des fichiers.", "La operación se canceló o tuvo un error; comprueba los archivos."],
        ["hubCleanupRepreview"] = ["أعد المعاينة قبل أي عملية أخرى؛ لا يُضمن إمكان التراجع في كل حالة.", "Preview again before another operation; undo is not guaranteed in every case.", "Refaites l’aperçu avant une autre opération ; l’annulation n’est pas toujours garantie.", "Vuelve a ver la vista previa antes de otra operación; deshacer no está garantizado en todos los casos."],
        ["hubCleanupFailed"] = ["تعذرت العملية أو تغيّرت الملفات منذ المعاينة. أعد المعاينة وراجع حالة الملفات.", "The operation failed or files changed after preview. Refresh the preview and check file state.", "Échec ou fichiers modifiés depuis l’aperçu. Actualisez et vérifiez leur état.", "Falló la operación o los archivos cambiaron tras la vista previa. Actualiza y comprueba su estado."],
        ["hubCleanupNoSelection"] = ["لا يوجد ملف محدد للإزالة. ابدأ بالمعاينة؛ لا يُختار شيء تلقائيًا.", "No files selected for removal. Start with Preview; nothing is selected automatically.", "Aucun fichier choisi. Commencez par l’aperçu ; aucune sélection automatique.", "No hay archivos seleccionados. Empieza con la vista previa; nada se selecciona automáticamente."],
        ["hubNoCleanupCandidates"] = ["لم تظهر ملفات مؤقتة مؤهلة ضمن هذه المعاينة المحدودة.", "No eligible temporary files were found in this bounded preview.", "Aucun fichier temporaire admissible trouvé dans cet aperçu limité.", "No se encontraron archivos temporales permitidos en esta vista previa limitada."],
        ["hubSearchPrivacy"] = ["الفهرس محلي ومحمي بحساب ويندوز وقد يحتوي مسارات ونصوصًا خاصة. اختر مجلدًا، ثم وافق إن أردت قراءة محتوياته. لا يُرسل الفهرس أو الاستعلام إلى خدمة ذكاء اصطناعي.", "The index is local, protected by your Windows account, and may contain private paths/text. Choose a folder, then opt into content reading if wanted. Neither index nor query is sent to AI.", "L’index local protégé par votre compte Windows peut contenir chemins et textes privés. Choisissez un dossier puis autorisez le contenu si souhaité. Ni index ni requête envoyés à l’IA.", "El índice es local, protegido por tu cuenta de Windows, y puede contener rutas y texto privados. Elige carpeta y autoriza leer contenido si lo deseas. Ni índice ni consulta se envían a la IA."],
        ["hubIndexContentConsent"] = ["أوافق على قراءة النص المدعوم من ملفات المجلد وحفظه في الفهرس المحلي", "Allow reading supported folder text and storing it in the local index", "Autoriser la lecture du texte pris en charge et son stockage dans l’index local", "Autorizar leer texto compatible de la carpeta y guardarlo en el índice local"],
        ["hubBuildIndex"] = ["بناء الفهرس المحلي", "Build local index", "Créer l’index local", "Crear índice local"],
        ["hubIndexProgress"] = ["جارٍ الفهرسة — ملفات مقروءة:", "Indexing — files processed:", "Indexation — fichiers traités :", "Indexando — archivos procesados:"],
        ["hubLoadIndex"] = ["فتح الفهرس المحفوظ", "Open saved index", "Ouvrir l’index enregistré", "Abrir índice guardado"],
        ["hubNoSavedIndex"] = ["لا يوجد فهرس محفوظ بعد.", "No saved index yet.", "Aucun index enregistré.", "Aún no hay un índice guardado."],
        ["hubNoIndexLoaded"] = ["ابنِ فهرسًا محليًا أو افتح فهرسًا محفوظًا أولًا.", "Build or load a local index first.", "Créez ou chargez un index local d’abord.", "Crea o carga primero un índice local."],
        ["hubSearchLimits"] = ["حدود الفهرس: حتى ١٠٠٠ ملف وقراءة محتوى حتى ٢٠٠ ملف ضمن ميزانية النص. يدعم النص وPDF وDOCX وXLSX وPPTX بقراءة جزئية محدودة. لا OCR للصور ولا تنسيقات Office القديمة. تفسير اللغة محلي بقواعد عربية وإنجليزية محددة، وليس بحثًا دلاليًا عامًا.", "Index limits: up to 1,000 files and content from up to 200 within a text budget. Text, PDF, DOCX, XLSX and PPTX use bounded partial extraction. No image OCR or legacy Office. Query interpretation uses limited local Arabic/English rules, not general semantic search.", "Limites : 1 000 fichiers et contenu de 200 au plus dans un budget texte. Texte, PDF, DOCX, XLSX et PPTX extraits partiellement. Pas d’OCR ni ancien Office. Interprétation locale par règles arabes/anglaises limitées, pas recherche sémantique générale.", "Límites: 1.000 archivos y contenido de hasta 200 dentro de un presupuesto de texto. Extracción parcial de texto, PDF, DOCX, XLSX y PPTX. Sin OCR ni Office antiguo. Interpretación local mediante reglas limitadas en árabe/inglés, no búsqueda semántica general."],
        ["hubIndexSummary"] = ["{0} ملف مفهرس · تاريخ البناء {1}", "{0} indexed files · built {1}", "{0} fichiers indexés · créé le {1}", "{0} archivos indexados · creado {1}"],
        ["hubQuery"] = ["البحث في الفهرس المحلي", "Search local index", "Rechercher dans l’index local", "Buscar en el índice local"],
        ["hubQueryExamples"] = ["مثال: «ابحث عن ملفات PDF عن التعريف الأسبوع الماضي» أو «find PDF files about driver last week». تُعرض طريقة تفسير الاستعلام أدناه.", "Example: “find PDF files about driver last week” or “ابحث عن ملفات PDF عن التعريف الأسبوع الماضي”. The interpreted filters appear below.", "Exemple : « find PDF files about driver last week » ou la requête arabe affichée. Les filtres interprétés apparaissent ci-dessous.", "Ejemplo: «find PDF files about driver last week» o la consulta árabe mostrada. Los filtros interpretados aparecen debajo."],
        ["hubStoredPreview"] = ["معاينة النص المخزّن في الفهرس", "Preview stored index text", "Aperçu du texte stocké", "Vista previa del texto almacenado"],
        ["hubQueryInterpretation"] = ["النوع: {0} · منذ UTC: {1} · الكلمات: {2}", "Type: {0} · Since UTC: {1} · Terms: {2}", "Type : {0} · Depuis UTC : {1} · Termes : {2}", "Tipo: {0} · Desde UTC: {1} · Términos: {2}"],
        ["hubAnyType"] = ["أي نوع مفهرس", "Any indexed type", "Tout type indexé", "Cualquier tipo indexado"],
