        ["hubSearchResultCount"] = ["{0} نتيجة مفهرسة مطابقة — حتى ١٠٠ نتيجة", "{0} matching indexed files (up to 100)", "{0} fichiers indexés correspondants (100 au maximum)", "{0} archivos indexados coincidentes (hasta 100)"],
        ["hubPreviewOnly"] = ["معاينة النص المحفوظ فقط؛ لا يُفتح الملف أو يُنفذ", "Preview stored text only; do not open or execute the file", "Aperçu du texte stocké uniquement ; sans ouvrir ni exécuter le fichier", "Solo vista previa del texto guardado; no abre ni ejecuta el archivo"],
        ["hubQueryInvalid"] = ["تعذر تفسير الاستعلام. استخدم عبارة أقصر أو كلمات مباشرة.", "Could not interpret the query. Use a shorter phrase or direct terms.", "Requête non interprétable. Utilisez une phrase plus courte ou des termes directs.", "No se pudo interpretar la consulta. Usa una frase más corta o términos directos."],
        ["hubFileTooLarge"] = ["المحتوى مستثنى بسبب حد الحجم؛ الاسم فقط", "Content excluded by size limit; name only", "Contenu exclu par limite de taille ; nom seul", "Contenido excluido por tamaño; solo nombre"],
        ["hubTextLimited"] = ["عينة نصية محدودة؛ قد لا تشمل كامل المستند", "Bounded text sample; may omit document content", "Échantillon texte limité ; document potentiellement incomplet", "Muestra de texto limitada; puede omitir contenido"],
        ["hubNoOcr"] = ["لم يُستخرج نص؛ لا تتوفر OCR للصور", "No text extracted; image OCR is unavailable", "Aucun texte extrait ; OCR d’image indisponible", "No se extrajo texto; OCR de imágenes no disponible"],
        ["hubNameOnly"] = ["اسم الملف فقط؛ المحتوى غير مفهرس", "File name only; content not indexed", "Nom du fichier seul ; contenu non indexé", "Solo nombre; contenido no indexado"],
        ["hubExtractorLimit"] = ["انتهت مهلة استخراج النص أو تجاوز حدوده؛ الاسم فقط", "Extraction timed out or exceeded limits; name only", "Extraction expirée ou limitée ; nom seul", "La extracción agotó tiempo o límites; solo nombre"],
        ["hubTimelinePrivacy"] = ["اجمع عينة محلية من الأحداث وتواريخ البرامج المبلّغ عنها ضمن الفترة المختارة. قد تحتوي أسماء برامج أو تفاصيل خاصة. الحفظ المحلي اختياري ولا تُشارك البيانات تلقائيًا.", "Collect local event samples and reported program dates for the selected period. Names/details may be private. Local saving is optional; nothing is shared automatically.", "Collectez des événements et dates déclarées de programmes sur la période choisie. Noms et détails peuvent être privés. Enregistrement facultatif, sans partage automatique.", "Recopila eventos locales y fechas de programas reportadas del período elegido. Nombres y detalles pueden ser privados. Guardar es opcional y nada se comparte automáticamente."],
        ["hubLookbackDays"] = ["آخر {0} يوم", "Past {0} days", "{0} derniers jours", "Últimos {0} días"],
        ["hubTimelineRange"] = ["فترة سجل التغييرات", "Timeline lookback period", "Période de la chronologie", "Período de la cronología"],
        ["hubCollectTimeline"] = ["جمع سجل التغييرات", "Collect timeline", "Collecter la chronologie", "Recopilar cronología"],
        ["hubSaveTimeline"] = ["حفظ لقطة السجل محليًا", "Save timeline locally", "Enregistrer la chronologie localement", "Guardar cronología localmente"],
        ["hubLoadTimeline"] = ["فتح لقطة سجل محفوظة", "Open saved timeline", "Ouvrir la chronologie enregistrée", "Abrir cronología guardada"],
        ["hubNoSavedTimeline"] = ["لا توجد لقطة سجل محفوظة بعد.", "No saved timeline yet.", "Aucune chronologie enregistrée.", "Aún no hay cronología guardada."],
        ["hubProblemOnset"] = ["وقت ظهور المشكلة (اختياري، محلي: yyyy-MM-dd HH:mm)", "Problem onset (optional, local: yyyy-MM-dd HH:mm)", "Début du problème (facultatif, local : yyyy-MM-dd HH:mm)", "Inicio del problema (opcional, local: yyyy-MM-dd HH:mm)"],
        ["hubTimelineShown"] = ["تُعرض {0} من {1} سجلات في العينة", "Showing {0} of {1} sampled records", "{0} enregistrements affichés sur {1} échantillonnés", "Mostrando {0} de {1} registros de la muestra"],
        ["hubLookbackUnavailable"] = ["فترة اللقطة المحفوظة غير مؤكدة؛ راجع أوقات الأحداث.", "Saved snapshot lookback is unknown; inspect event times.", "Période de la capture inconnue ; vérifiez les heures des événements.", "Se desconoce el período de la captura; revisa las horas de eventos."],
        ["hubChronologyOnly"] = ["تُعرض أحداث تسبق الوقت المحدد بما يصل إلى ٤٨ ساعة. السبق الزمني ليس دليلًا على السببية، وقد تكون السجلات ناقصة.", "Shows events up to 48 hours before the selected time. Precedence does not prove causation, and logs may be incomplete.", "Événements jusqu’à 48 heures avant l’heure choisie. L’antériorité ne prouve pas la causalité ; journaux parfois incomplets.", "Muestra eventos hasta 48 horas antes de la hora elegida. La precedencia no demuestra causalidad y los registros pueden estar incompletos."],
        ["hubTimelineLimits"] = ["سجل محدود من قنوات ويندوز وتواريخ البرامج، وقد تغيب قنوات أو أحداث قديمة. أحداث التعريف ليست دليلًا على أن تاريخ إصدار التعريف هو تاريخ تثبيته؛ يجب مراجعة محتوى الحدث.", "A bounded sample of Windows channels and program dates; channels or older events may be missing. Driver events do not turn a driver release date into an installation date; inspect the event.", "Échantillon limité de canaux Windows et dates de programmes ; certains peuvent manquer. Les événements pilotes ne transforment pas une date de publication en date d’installation ; examinez l’événement.", "Muestra limitada de canales Windows y fechas de programas; pueden faltar canales o eventos antiguos. Los eventos no convierten la fecha de publicación del controlador en fecha de instalación; revisa el evento."],
        ["hubRegistryDateLimits"] = ["تاريخ أبلغ عنه سجل البرامج؛ قد يعكس صيانة أو تحديثًا ولا يثبت تاريخ التثبيت الأصلي.", "Date reported by program registry; may reflect servicing or updates, not original installation.", "Date déclarée dans le registre ; peut refléter maintenance ou mise à jour, pas l’installation initiale.", "Fecha reportada por el registro; puede reflejar mantenimiento o actualización, no instalación original."],
        ["hubCrashEvent"] = ["حدث خطأ أو تعطل من Application", "Application error/crash event", "Événement erreur/plantage Application", "Evento de error/fallo de Application"],
        ["hubSystemEvent"] = ["حدث خطأ من System", "System error event", "Événement d’erreur System", "Evento de error de System"],
        ["hubUpdateEvent"] = ["حدث إعداد أو تحديث", "Setup/update event", "Événement installation/mise à jour", "Evento de configuración/actualización"],
        ["hubDriverEvent"] = ["حدث إعداد جهاز أو تعريف", "Device/driver configuration event", "Événement de configuration périphérique/pilote", "Evento de configuración de dispositivo/controlador"],
        ["hubProgramDate"] = ["تاريخ برنامج مبلّغ عنه", "Reported program date", "Date de programme déclarée", "Fecha de programa reportada"],
        ["hubUsbLimits"] = ["قراءة لأجهزة USB المعروضة عبر PnP ومخزون الأقراص والوحدات القابلة للإزالة. قد تكون بعض المصادر غير متاحة، ولا يثبت اسم الجهاز أو غياب خطأ سلامة الوسيط. لا تُكتب بيانات ولا يُعدّل تعريف.", "Reads USB PnP devices, disk inventory and removable volumes. Sources may be unavailable; a device name or no reported error does not certify media health. No writes or driver changes.", "Lecture des périphériques USB PnP, disques et volumes amovibles. Sources parfois indisponibles ; nom ou absence d’erreur ne certifie pas le support. Aucune écriture ni modification de pilote.", "Lee dispositivos USB PnP, inventario de discos y volúmenes extraíbles. Pueden faltar fuentes; un nombre o ausencia de errores no certifica el medio. Sin escrituras ni cambios de controlador."],
        ["hubUsbDevice"] = ["جهاز USB في العينة", "Sampled USB device", "Périphérique USB échantillonné", "Dispositivo USB de la muestra"],
        ["hubUsbDisk"] = ["قرص USB في المخزون", "USB disk inventory entry", "Disque USB dans l’inventaire", "Disco USB en el inventario"],
        ["hubRemovableVolume"] = ["وحدة تخزين قابلة للإزالة", "Removable volume", "Volume amovible", "Volumen extraíble"],
        ["hubNoDevices"] = ["لم تُرجع المصادر المقروءة أجهزة في هذه العينة", "Readable sources returned no devices in this sample", "Les sources lisibles n’ont retourné aucun périphérique", "Las fuentes legibles no devolvieron dispositivos en esta muestra"],
        ["hubRefreshUsb"] = ["قراءة الأجهزة الخارجية", "Read external devices", "Lire les périphériques externes", "Leer dispositivos externos"],
        ["hubReadTest"] = ["اختبار قراءة غير مدمر", "Non-destructive read test", "Test de lecture non destructif", "Prueba de lectura no destructiva"],
        ["hubReadTestLimits"] = ["يقرأ الملف المحدد مرتين، حتى أول ٦٤ MiB في كل مرور، دون كتابة. قد تؤثر ذاكرة ويندوز المؤقتة والبرامج الأخرى في السرعة والمطابقة. تطابق العينة لا يثبت سلامة كامل الوسيط؛ اختلافها قد ينتج عن تغيّر الملف.", "Reads the selected file twice, at most its first 64 MiB per pass, without writing. Windows cache and other programs affect speed/matches. Matching samples do not certify the whole medium; differences may reflect file changes.", "Lit deux fois le fichier choisi, au plus ses 64 premiers Mio par passage, sans écriture. Cache Windows et autres programmes influencent vitesse et correspondance. Une correspondance ne certifie pas le support ; un écart peut venir du fichier.", "Lee dos veces el archivo elegido, como máximo sus primeros 64 MiB por pasada, sin escribir. La caché y otros programas afectan velocidad y coincidencias. Coincidir no certifica todo el medio; diferir puede deberse a cambios del archivo."],
        ["hubUsbTestFile"] = ["الملف المختار لاختبار القراءة", "Selected read-test file", "Fichier choisi pour le test de lecture", "Archivo elegido para prueba de lectura"],
        ["hubReadConsent"] = ["أوافق على قراءة عينة من هذا الملف مرتين دون كتابة", "Allow reading this file sample twice without writing", "Autoriser deux lectures de cet échantillon sans écriture", "Autorizar dos lecturas de esta muestra sin escribir"],
        ["hubRunReadTest"] = ["بدء اختبار القراءة", "Run read test", "Lancer le test de lecture", "Ejecutar prueba de lectura"],
        ["hubReadConsentRequired"] = ["اختر ملفًا على وحدة خارجية ووافق على قراءة العينة أولًا.", "Choose an external-storage file and approve sample reading first.", "Choisissez un fichier externe et autorisez d’abord la lecture.", "Elige un archivo externo y autoriza primero la lectura de muestra."],
        ["hubReadBytes"] = ["البايتات المقروءة في المرورين", "Bytes read across both passes", "Octets lus sur les deux passages", "Bytes leídos en ambas pasadas"],
        ["hubReadRate"] = ["معدل قراءة العينة", "Sample read rate", "Débit de lecture de l’échantillon", "Velocidad de lectura de la muestra"],
