        ["hubSamplesDiffer"] = ["اختلفت العينة أو تغيّرت بيانات الملف؛ النتيجة غير حاسمة", "Samples or file metadata changed; result is inconclusive", "Échantillons ou métadonnées modifiés ; résultat non concluant", "Cambiaron muestras o metadatos; resultado no concluyente"],
